<html>
<head>
  <style>
    canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <h1>Pendulum Simulator</h1>
  <p>
    <input id="initial-angle" type="number" min="0" max="90" value="45">
    <button id="release-button">Release Pendulum</button>
  </p>
  <canvas id="canvas" width="400" height="400"></canvas>
  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const initialAngle = document.getElementById('initial-angle');
    const releaseButton = document.getElementById('release-button');

    let angle = 0;
    let velocity = 0;
    let gravity = 0.1;
    let mass = 0.1;
    let length = 100;

    let animationFrameId = null;
    let isReleased = false;

    function update() {
      if (isReleased) {
        angle += velocity;
        velocity -= gravity / length * Math.sin(Math.PI / 180 * angle);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, length, (Math.PI / 180 * (angle - 90)) * Math.PI, (Math.PI / 180 * (angle + 90)) * Math.PI);
        ctx.stroke();
      } else {
        animationFrameId = null;
      }
    }

    function animate() {
      if (animationFrameId !== null) {
        requestAnimationFrame(animate);
      }
      update();
    }

    releaseButton.addEventListener('click', () => {
      isReleased = true;
      angle = parseInt(initialAngle.value) * Math.PI / 180;
      velocity = 0;
      animationFrameId = requestAnimationFrame(animate);
    });

    animate();
  </script>
</body>
</html>
```

